        tenant,
        data["did"],
        data["public_key"],
        data["key_version"],
    )
    # 新建 201；同 DID/版本同 PEM 幂等重试 200；PEM 不同由
    # store 抛 ConflictError -> 409。
    self._send_json(
        201 if created else 200,
