    self._send_json(
        200, [self._trust_anchor_payload(r) for r in records]
    )

def _put_trust_anchor_status(
    self, tenant: str, did: str, key_version: str
) -> None:
    # 请求体必须恰为 {"status": "revoked"}；路径 key_version
    # 须为非布尔正整数（路径参数为字符串）。
